# Bounded source preflight only. No task, process, lock, desktop or qualification action.
[CmdletBinding()]
param([Parameter(Mandatory)][string]$StageRoot)
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
function Read-Bounded([string]$p){$i=Get-Item -LiteralPath $p -Force;if(($i.Attributes -band [IO.FileAttributes]::ReparsePoint)-ne 0 -or $i.Length -gt 2097152){throw "bounded preflight read rejected: $p"};return [IO.File]::ReadAllText($i.FullName)|ConvertFrom-Json}
function Require([bool]$ok,[string]$m){if(-not $ok){throw $m}}
$stage=[IO.Path]::GetFullPath($StageRoot);Require (Test-Path -LiteralPath $stage -PathType Container) "stage missing: $stage";$pins=Read-Bounded (Join-Path $stage 'source-pins-r8.json');$plan=Read-Bounded (Join-Path $stage 'one-run-plan-r8.json');Require ([string]$pins.schema -eq 'sr0-display-selfjob-v4-source-pins-r8') 'source pin schema mismatch';Require ([string]$plan.schema -eq 'sr0-display-selfjob-v4-fresh-one-run-r8') 'source plan schema mismatch';Require ([int64]$plan.aggregateJobMemoryLimitBytes -eq 1073741824) '1GiB aggregate bound missing';Require ([int]$plan.deadlineSeconds -eq 900 -and [int]$plan.pollSeconds -eq 1) 'collector bounds mismatch';Require ([bool]$plan.noActivate -and [bool]$plan.noResources) 'NoActivate/NoResources missing';Require (-not [bool]$plan.qualificationClaim -and [int]$plan.nativeActions -eq 0) 'preflight must remain non-native'
$verified=0;foreach($f in @($pins.files)){$p=[string]$f.path;if([bool]$f.external){$p=[string]$f.path}else{$p=Join-Path $stage ($p.Replace('/','\'))};$i=Get-Item -LiteralPath $p -Force;Require (($i.Attributes -band [IO.FileAttributes]::ReparsePoint)-eq 0) "reparse source: $p";Require ([int64]$i.Length -eq [int64]$f.bytes) "source byte drift: $p";Require ((Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant() -ceq ([string]$f.sha256).ToLowerInvariant()) "source hash drift: $p";$verified++};Require ($verified -eq @($pins.files).Count) 'source verification count mismatch';$out=[ordered]@{schema='sr0-display-selfjob-v4-preflight-r8';status='passed-source-preflight';stage=$stage;verifiedSources=$verified;nativeActions=0;lockActions=0;qualificationClaim=$false;execution='not run';planSha256=(Get-FileHash -LiteralPath (Join-Path $stage 'one-run-plan-r8.json') -Algorithm SHA256).Hash.ToLowerInvariant();pinsSha256=(Get-FileHash -LiteralPath (Join-Path $stage 'source-pins-r8.json') -Algorithm SHA256).Hash.ToLowerInvariant()};$out|ConvertTo-Json -Depth 8
